import java.util.Arrays;

public class ArraysStringsTour {
    // prefix[i] = sum of the first i values, so any range sum costs O(1)
    static int[] prefixSums(int[] values) {
        int[] prefix = new int[values.length + 1];
        for (int i = 0; i < values.length; i++) {
            prefix[i + 1] = prefix[i] + values[i];
        }
        return prefix;
    }

    // Fixed-size sliding window: add the element entering, subtract the one leaving
    static int bestWindowStart(int[] values, int k) {
        int window = 0;
        for (int i = 0; i < k; i++) window += values[i];
        int best = window, bestStart = 0;
        for (int right = k; right < values.length; right++) {
            window += values[right] - values[right - k];
            if (window > best) {
                best = window;
                bestStart = right - k + 1;
            }
        }
        return bestStart;
    }

    // Two pointers walking toward each other
    static boolean isPalindrome(String text) {
        int left = 0, right = text.length() - 1;
        while (left < right) {
            if (text.charAt(left) != text.charAt(right)) return false;
            left++;
            right--;
        }
        return true;
    }

    public static void main(String[] args) {
        int[] steps = {4200, 8100, 6500, 12000, 3000, 9800, 11000};
        int[] prefix = prefixSums(steps);
        System.out.println("Steps per day: " + Arrays.toString(steps));
        System.out.println("Prefix sums:   " + Arrays.toString(prefix));
        System.out.println("Days 2..4 total = prefix[5] - prefix[2] = " + (prefix[5] - prefix[2]));

        int start = bestWindowStart(steps, 3);
        int[] best = Arrays.copyOfRange(steps, start, start + 3);
        System.out.println("Best 3-day window starts at day " + start + ": " + Arrays.toString(best));

        int[] sorted = steps.clone();
        Arrays.sort(sorted);
        System.out.println("Sorted copy: " + Arrays.toString(sorted) + ", median = " + sorted[sorted.length / 2]);

        for (String word : new String[]{"racecar", "level", "atlas"}) {
            System.out.println(word + " is a palindrome? " + isPalindrome(word));
        }
    }
}

import java.util.Arrays;

public class ArrayTraversal {
    // One pass collects several facts; every index stays in 0..length-1
    static void summarize(String label, int[] scores) {
        if (scores.length == 0) {
            System.out.println(label + ": empty array, nothing to summarize");
            return;
        }
        int sum = 0;
        int maxIndex = 0;                       // index of a real element, not the value 0
        for (int i = 0; i < scores.length; i++) {
            sum += scores[i];
            if (scores[i] > scores[maxIndex]) maxIndex = i;
        }
        double average = (double) sum / scores.length;
        int aboveAverage = 0;
        for (int score : scores) {              // second pass: needs the finished average
            if (score > average) aboveAverage++;
        }
        System.out.printf("%s: n=%d sum=%d max=%d at index %d avg=%.2f above avg=%d%n",
                label, scores.length, sum, scores[maxIndex], maxIndex, average, aboveAverage);
    }

    public static void main(String[] args) {
        int[] scores = {72, 95, 88, 61, 95, 79};
        summarize("quiz scores", scores);
        summarize("temperatures", new int[]{-4, -9, -1, -7});
        summarize("no scores", new int[0]);

        // Backwards: start at length - 1 and include index 0
        StringBuilder backwards = new StringBuilder();
        for (int i = scores.length - 1; i >= 0; i--) {
            backwards.append(scores[i]);
            if (i > 0) backwards.append(' ');
        }
        System.out.println("backwards: " + backwards);

        // Running maximum: each slot stores the best value seen so far
        int[] runningMax = new int[scores.length];
        for (int i = 0; i < scores.length; i++) {
            runningMax[i] = i == 0 ? scores[0] : Math.max(runningMax[i - 1], scores[i]);
        }
        System.out.println("running max: " + Arrays.toString(runningMax));
    }
}

public class StringMethods {
    public static void main(String[] args) {
        String email = "ada.lovelace@atlas.dev";
        int at = email.indexOf('@');
        System.out.println("length = " + email.length());
        System.out.println("charAt(0) = " + email.charAt(0));
        System.out.println("indexOf('@') = " + at);
        System.out.println("user = " + email.substring(0, at));      // end index is exclusive
        System.out.println("domain = " + email.substring(at + 1));
        System.out.println("indexOf(\"xyz\") = " + email.indexOf("xyz")); // -1 means not found

        // Strings are immutable: toUpperCase returns a NEW string
        String name = "ada";
        String upper = name.toUpperCase();
        System.out.println("name = " + name + ", upper = " + upper);

        // Compare content with equals; == compares object identity
        String literal = "cat";
        String built = new StringBuilder("c").append("at").toString();
        System.out.println("same content: " + literal.equals(built));
        System.out.println("same object: " + (literal == built));

        // Build text in a loop with StringBuilder: O(n) instead of O(n^2) copying
        StringBuilder initials = new StringBuilder();
        for (String word : "data structures and algorithms".split(" ")) {
            initials.append(Character.toUpperCase(word.charAt(0)));
        }
        System.out.println("initials = " + initials);

        // Count characters with one pass of charAt
        int vowels = 0;
        for (int i = 0; i < email.length(); i++) {
            if ("aeiou".indexOf(email.charAt(i)) >= 0) vowels++;
        }
        System.out.println("vowels in email = " + vowels);
    }
}

import java.util.Arrays;

public class TwoPointers {
    static void reverseInPlace(int[] a) {
        int left = 0, right = a.length - 1;
        while (left < right) {
            int tmp = a[left];
            a[left] = a[right];
            a[right] = tmp;
            left++;
            right--;
        }
    }

    static boolean isPalindrome(String s) {
        int left = 0, right = s.length() - 1;
        while (left < right) {
            if (!Character.isLetterOrDigit(s.charAt(left))) { left++; continue; }
            if (!Character.isLetterOrDigit(s.charAt(right))) { right--; continue; }
            if (Character.toLowerCase(s.charAt(left)) != Character.toLowerCase(s.charAt(right))) return false;
            left++;
            right--;
        }
        return true;
    }

    // Requires a sorted array: each step rules out one element for good
    static void pairWithSum(int[] sorted, int target) {
        int left = 0, right = sorted.length - 1;
        while (left < right) {
            int sum = sorted[left] + sorted[right];
            System.out.println("  left=" + left + " right=" + right + " sum=" + sum);
            if (sum == target) {
                System.out.println("  found " + sorted[left] + " + " + sorted[right] + " = " + target);
                return;
            }
            if (sum < target) left++;   // need a bigger sum
            else right--;               // need a smaller sum
        }
        System.out.println("  no pair adds up to " + target);
    }

    public static void main(String[] args) {
        int[] values = {1, 2, 3, 4, 5, 6};
        reverseInPlace(values);
        System.out.println("reversed: " + Arrays.toString(values));

        System.out.println("palindrome? " + isPalindrome("A man, a plan, a canal: Panama"));
        System.out.println("palindrome? " + isPalindrome("Two pointers!"));

        int[] prices = {3, 8, 11, 15, 21, 26};
        System.out.println("pair summing to 32 in " + Arrays.toString(prices) + ":");
        pairWithSum(prices, 32);
        System.out.println("pair summing to 10:");
        pairWithSum(prices, 10);
    }
}

import java.util.HashMap;
import java.util.Map;

public class SlidingWindow {
    static void bestFixedWindow(int[] sales, int k) {
        int window = 0;
        for (int i = 0; i < k; i++) window += sales[i];
        int best = window, bestLeft = 0;
        System.out.println("  window [0.." + (k - 1) + "] sum=" + window);
        for (int right = k; right < sales.length; right++) {
            window += sales[right] - sales[right - k];   // one in, one out
            int left = right - k + 1;
            System.out.println("  window [" + left + ".." + right + "] sum=" + window);
            if (window > best) {
                best = window;
                bestLeft = left;
            }
        }
        System.out.println("  best: days " + bestLeft + ".." + (bestLeft + k - 1) + " with " + best);
    }

    static String longestUnique(String s) {
        Map<Character, Integer> lastSeen = new HashMap<>();
        int left = 0, bestLeft = 0, bestLen = 0;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            if (lastSeen.containsKey(c) && lastSeen.get(c) >= left) {
                left = lastSeen.get(c) + 1;               // shrink past the repeat
            }
            lastSeen.put(c, right);
            if (right - left + 1 > bestLen) {
                bestLen = right - left + 1;
                bestLeft = left;
            }
            System.out.println("  right=" + right + " '" + c + "' window=\"" + s.substring(left, right + 1) + "\"");
        }
        return s.substring(bestLeft, bestLeft + bestLen);
    }

    public static void main(String[] args) {
        int[] sales = {5, 1, 7, 3, 8, 2, 6};
        System.out.println("Best 3-day sales window:");
        bestFixedWindow(sales, 3);
        System.out.println("Longest substring without repeats in \"abcabcbb\":");
        String answer = longestUnique("abcabcbb");
        System.out.println("  answer: \"" + answer + "\" (length " + answer.length() + ")");
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;

public class ArraySorting {
    record Player(String name, String team, int score) {
        @Override
        public String toString() { return name + "(" + team + "," + score + ")"; }
    }

    public static void main(String[] args) {
        int[] numbers = {42, 7, 19, 7, 88, 3, 19};
        int[] sorted = numbers.clone();          // keep the original untouched
        Arrays.sort(sorted);
        System.out.println("original: " + Arrays.toString(numbers));
        System.out.println("sorted:   " + Arrays.toString(sorted));

        // Equal values are now neighbours: one pass finds duplicates
        List<Integer> duplicates = new ArrayList<>();
        for (int i = 1; i < sorted.length; i++) {
            if (sorted[i] == sorted[i - 1]) duplicates.add(sorted[i]);
        }
        System.out.println("duplicates: " + duplicates);

        List<Player> players = new ArrayList<>(List.of(
                new Player("Rin", "red", 70), new Player("Ana", "blue", 90),
                new Player("Leo", "red", 90), new Player("Mia", "blue", 70)));
        players.sort(Comparator.comparingInt(Player::score).reversed().thenComparing(Player::name));
        System.out.println("by score desc, then name: " + players);

        // Stable: within each team, the score order above is kept
        players.sort(Comparator.comparing(Player::team));
        System.out.println("then by team (stable):    " + players);

        String[] names = {"adam", "Zoe", "bea", "Carl"};
        String[] byCode = names.clone();
        Arrays.sort(byCode);
        String[] ignoreCase = names.clone();
        Arrays.sort(ignoreCase, String.CASE_INSENSITIVE_ORDER);
        System.out.println("by char code: " + Arrays.toString(byCode));
        System.out.println("ignore case:  " + Arrays.toString(ignoreCase));
    }
}

